@GetMapping(value = "/{ownerId}")
public Optional<Map<String, Object>> findOwner(@PathVariable("ownerId") @Min(1) int ownerId) {
    return ownerRepository.findById(ownerId).map(owner -> {
        Map<String, Object> response = new LinkedHashMap<>();
        response.put("id", owner.getId());
        response.put("firstName", owner.getFirstName());
        response.put("lastName", owner.getLastName());
        response.put("address", owner.getAddress());
        response.put("city", owner.getCity());
        response.put("telephone", owner.getTelephone());
        response.put("animals", owner.getPets());
        return response;
    });
}

